/usr/bin/zsh -lc "cat > candidate.sv <<'SV'
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic w,
    output logic z
);
    localparam logic [2:0] A = 3'd0, B = 3'd1, C = 3'd2,
                           D = 3'd3, E = 3'd4, F = 3'd5;
    logic [2:0] state_r, state_n;

    always_comb begin
        state_n = A;
        case (state_r)
            A: state_n = w ? A : B;
            B: state_n = w ? D : C;
            C: state_n = w ? D : E;
            D: state_n = w ? A : F;
            E: state_n = w ? D : E;
            F: state_n = w ? D : C;
            default: state_n = A;
        endcase
    end

    always_ff @(posedge clk) begin
        if (reset)
            state_r <= A;
        else
            state_r <= state_n;
    end

    assign z = (state_r == E) || (state_r == F);
endmodule
SV
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'SV'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic reset = 0;
    logic w = 0;
    wire z;
    integer ref_state = 0;
    integer checks = 0;
    integer covered [0:5][0:1];
    integer reset_covered [0:5][0:1];
    integer transitions [0:5][0:1];
    integer sequence_id, bit_id, s, b;
    TopModule dut (.clk(clk), .reset(reset), .w(w), .z(z));

    task automatic step(input bit rst, input bit inp);
        logic previous_z;
        begin
            previous_z = z;
            reset = rst;
            w = inp;
            #2;
            if (checks > 0 && z !== previous_z)
                $fatal(1, "Output changed between clock edges");
            if (rst) begin
                if (checks > 0) reset_covered[ref_state][inp] = 1;
                ref_state = 0;
            end else begin
                covered[ref_state][inp] = 1;
                ref_state = transitions[ref_state][inp];
            end
            clk = 1;
            #1;
            if (z !== ((ref_state == 4) || (ref_state == 5)))
                $fatal(1, "Mismatch check=%0d state=%0d z=%b", checks, ref_state, z);
            checks = checks + 1;
            #1;
            clk = 0;
            #1;
        end
    endtask

    initial begin
        transitions[0][0]=1; transitions[0][1]=0;
        transitions[1][0]=2; transitions[1][1]=3;
        transitions[2][0]=4; transitions[2][1]=3;
        transitions[3][0]=5; transitions[3][1]=0;
        transitions[4][0]=4; transitions[4][1]=3;
        transitions[5][0]=2; transitions[5][1]=3;
        for (s=0; s<6; s=s+1)
            for (b=0; b<2; b=b+1) begin
                covered[s][b]=0;
                reset_covered[s][b]=0;
            end
        for (sequence_id=0; sequence_id<1024; sequence_id=sequence_id+1) begin
            step(1, 0);
            for (bit_id=0; bit_id<10; bit_id=bit_id+1)
                step(0, (sequence_id >> bit_id) & 1);
            step(1, sequence_id & 1);
        end
        for (s=0; s<6; s=s+1)
            for (b=0; b<2; b=b+1) begin
                if (!covered[s][b]) $fatal(1, "Missing transition %0d/%0d", s,b);
                if (!reset_covered[s][b]) $fatal(1, "Missing reset %0d/%0d", s,b);
            end
        $display("PASS: %0d checked cycles; all 12 transitions and all 12 state/reset-input cases", checks);
        $finish;
    end
    initial begin
        #100000;
        $fatal(1, "Testbench timeout");
    end
endmodule
SV
