/usr/bin/zsh -lc "cp dev_tb.sv dev_tb_initial.sv
python3 - <<'PY'
p='dev_tb.sv'
s=open(p).read().replace('integer covered [0:5][0:1];','integer covered [0:11];').replace('integer reset_covered [0:5][0:1];','integer reset_covered [0:11];').replace('integer transitions [0:5][0:1];','''function automatic integer next_state(input integer current_state, input bit inp);
        case (current_state)
            0: next_state = inp ? 0 : 1;
            1: next_state = inp ? 3 : 2;
            2: next_state = inp ? 3 : 4;
            3: next_state = inp ? 0 : 5;
            4: next_state = inp ? 3 : 4;
            5: next_state = inp ? 3 : 2;
            default: next_state = 0;
        endcase
    endfunction''').replace('reset_covered[ref_state][inp]', 'reset_covered[ref_state*2+inp]').replace('covered[ref_state][inp]', 'covered[ref_state*2+inp]').replace('transitions[ref_state][inp]', 'next_state(ref_state, inp)').replace('covered[s][b]', 'covered[s*2+b]').replace('reset_covered[s][b]', 'reset_covered[s*2+b]')
s='\\n'.join(line for line in s.split('\\n') if not line.strip().startswith('transitions['))
open(p,'w').write(s)
PY
